-- 线性表模块：顺序表连续存储与按下标直接寻址。
INSERT INTO knowledge_point (name, description, course_id, parent_id, content_key, content_source, content_version, content_review_status, sort_order, deleted)
SELECT '顺序表的存储表示', '顺序表将逻辑相邻元素放在物理连续位置，LOC(ai)=LOC(a1)+(i-1)l，支持 O(1) 随机访问。', course.id, parent.id, 'cs408-sequential-list-storage', 'AISTU', 1, 'REVIEWED', 2, 0
FROM course JOIN knowledge_point parent ON parent.course_id=course.id AND parent.content_key='408-linear-lists' LEFT JOIN knowledge_point existing ON existing.content_key='cs408-sequential-list-storage'
WHERE course.content_key='cs408-data-structures' AND existing.id IS NULL;
INSERT INTO tutor_content (knowledge_point_id, content_key, content_version, review_status, title, lesson_json, check_json)
SELECT point.id,'cs408-sequential-list-storage',1,'REVIEWED','顺序表的存储表示',JSON_OBJECT('summary','顺序表把逻辑相邻元素放在物理连续位置。若首元素地址为 LOC(a1)、每个元素占 l 字节，则 LOC(ai)=LOC(a1)+(i-1)l，因此可按下标 O(1) 定位；长度与容量仍需分别维护。','steps',JSON_ARRAY('逻辑相邻对应物理连续','首地址加上固定宽度的偏移即可定位元素','第 i 个元素的偏移为 (i-1)l','直接寻址不代表中间插删无需搬移'),'visualization',JSON_OBJECT('kind','SEQUENTIAL_LIST_STORAGE','version',1,'baseAddress',1000,'elementWidth',4,'elements',JSON_ARRAY('A','B','C','D'),'accessIndex',2),'prerequisite',JSON_OBJECT('contentKey','cs408-linear-list-definition-operations','title','线性表的定义与基本操作','description','先确认顺序表实现的是同一个线性表逻辑序列。'),'nextStep',JSON_OBJECT('contentKey','cs408-sequential-list-insert-delete','title','顺序表的插入与删除','description','继续理解连续存储在中间更新时为何需要搬移后缀。')),JSON_OBJECT('id','sequential-list-storage-v1','prompt','首元素地址为 1000，每个元素占 4 字节时，第三个元素 a3 的地址是多少？','options',JSON_ARRAY(JSON_OBJECT('id','OFFSET_EIGHT','text','1008，因为偏移为 (3-1)×4'),JSON_OBJECT('id','OFFSET_TWELVE','text','1012，因为第三个元素的偏移为 3×4')),'correctOptionId','OFFSET_EIGHT','correctExplanation','正确：a3 相对首元素经过两个元素宽度，地址为 1000+2×4=1008。','incorrectExplanation','不正确：下标从第一个元素开始时，偏移是 i-1 个元素宽度。') FROM knowledge_point point LEFT JOIN tutor_content existing ON existing.content_key='cs408-sequential-list-storage' AND existing.content_version=1 WHERE point.content_key='cs408-sequential-list-storage' AND existing.id IS NULL;
